    45	    Integer getTitleLineIndex(List<String> lines) {
    46	        Integer titleLineIndex = -1
    47	        for (String line : lines) {
    48	            titleLineIndex++
    49	            if (line && StringUtils.isNotBlank(line) && StringUtils.isNotEmpty(line)) {
