    56	    public void parsePDFStatementForTransactions(ProcessedBankStatementVO processedBankStatementVO) {
    57	        File textFile = processedBankStatementVO.processBankStatementCO.textFile
    58	        String fileContent = textFile.getText('UTF-8')
    59	        try {
    60	            Boolean flag = Boolean.FALSE
    61	            Boolean isMergedStatement = Boolean.FALSE
    62	            Boolean downloadedSavingTypeTwo = Boolean.FALSE
    63	            List<String> lines = FileUtils.readLines(textFile)
    64	            String titleLine = lines.get(getTitleLineIndex(lines))
    65	            Scanner scanner = new Scanner(textFile)
    66	            while (scanner.hasNextLine()) {
    67	                String nextToken = scanner.nextLine()
    68	                if (nextToken.equalsIgnoreCase("Statement of Banking Account")) {
    69	                    if (flag) {
    70	                        isMergedStatement = Boolean.TRUE
    71	                        flag = Boolean.FALSE
    72	                        break
    73	                    }
    74	                    flag = Boolean.TRUE
    75	                }
    76	                if (nextToken.find("Statement[\\s]*of[\\s]*Account[\\s]*for[\\s]*the[\\s]*Period")) {
    77	                    downloadedSavingTypeTwo = Boolean.TRUE
    78	                    break
    79	                }
    80	            }
    81	            if (flag || downloadedSavingTypeTwo) {
    82	                log.debug("=== Parsing Emailed KOTAK Statement ***********")
    83	                BankTransactionUtil.extractTransactions(processedBankStatementVO)
    84	            } else if (isMergedStatement) {
    85	                log.debug("=== Parsing Merged Emailed KOTAK Statement ***********")
    86	                KotakBankUtil.extractTransactionsFromMergedEStatementSavingAccount(processedBankStatementVO)
    87	            } else if (titleLine && titleLine.toLowerCase().contains("account statement")) {
    88	//                TODO : Make this condition better
    89	                if (fileContent.toUpperCase().find("[.][\\s]*DATE[\\s]*DESCRIPTION[\\s]*REF/CHQ NO[\\s]*WITH[\\s]*DRAWALS[\\s]*DEPOSITS[\\s]*BALANCES")) {
    90	                    log.debug("=== Parsing Kotak Saving Account Statement Type Three***********")
    91	                    KotakBankUtil.extractTransactionsFromDownloadedSavingAccountTypeThree(processedBankStatementVO)
    92	                } else {
    93	                    log.debug("=== Parsing Kotak Current Account Statement ***********")
    94	                    KotakBankUtil.extractTransactionsFromDownloadedCurrentAccount(processedBankStatementVO)
    95	//                    BankTransactionUtil.extractTransactions(processedBankStatementVO)
    96	                }
    97	            } else {
    98	                log.debug("=== Parsing Downloaded KOTAK Statement ***********")
    99	                BankTransactionUtil.extractTransactions(processedBankStatementVO)
   100	            }
   101	        } catch (Exception e) {
   102	            processedBankStatementVO.statementStatus.message = "Error occured during parsing pdf file for Kotak bank statement transactions.  ${e.message}"
   103	            processedBankStatementVO.statementStatus.exceptionStackTrace = AppUtil.getStackTraceAsString(e)
   104	            processedBankStatementVO.statementStatus.statementParsedStatus = Enums.StatementParsedStatus.ERROR
