    static void extractBasicInformationFromDownloadedCurrentAccount(ProcessedBankStatementVO processedBankStatementVO) {
//      Unit test for method is written in KotakBankUtilSpec with name "7: Kotak Bank : extractBasicInformationFromDownloadedCurrentAccount()"
        String dateRegex = "[0-3]?[0-9]/[0-1]?[0-9]/(?:[0-9]{2})?[0-9]{2}"
        String dateFormat = "dd/MM/yyyy"
        File file = processedBankStatementVO.processBankStatementCO.textFile
        if (!AppUtil.isValidStatementFile(file, ["Account[\\s]*Statement", "Account[\\s]*No", "Branch"])) {
            return
        }
        BufferedReader reader = new BufferedReader(new InputStreamReader(new FileInputStream(file), "UTF-8"))
        BasicDetailsResponse basicDetails = processedBankStatementVO.basicDetails
        Boolean openingBalanceNotSet = Boolean.TRUE
        String line = ""
        while (line != null) {
            line = reader.readLine()
            if (StringUtils.isBlank(line) || line.find("Closing[\\s]+balance")) {
                continue
            } else if (line.find("Account[\\s]+Statement")) {
                line = reader.readLine().trim()
                if (!line) {
                    line = reader.readLine()
                    basicDetails.accountHolderName = line.split("Account")[0].trim()
                    basicDetails.accountNumber = line.find("[0-9]{10}")
                } else {
                    basicDetails.accountHolderName = line
                }
            } else if (line.find("Account[\\s]+No")) {
                basicDetails.accountNumber = line.split("Account[\\s]+No")[1].replace(".", "").trim()
            } else if (openingBalanceNotSet && line.find("Opening[\\s]+balance")) {
                Double openingBalance = HelperMethod.getSanitizeDouble(line.find("[+-]?[0-9]{1,3}(?:,?[0-9]{3})*\\.[0-9]{2}").trim())
                processedBankStatementVO.bankTransactionList << BankUtil.createOpeningBalanceTransaction(openingBalance)
                openingBalanceNotSet = Boolean.FALSE
            } else if (line.contains("Period") && line.contains("From") && line.contains("To")) {
                Pattern datePattern = Pattern.compile(dateRegex)
                Matcher dateMatcher = datePattern.matcher(line)
                List<String> dateList = []
                while (dateMatcher.find()) {
                    dateList << dateMatcher.group()
                }
                if (dateList.size() == 2) {
                    String fromDate = dateList.get(0)
                    String toDate = dateList.get(1)
                    SimpleDateFormat format = new SimpleDateFormat(dateFormat)
                    basicDetails.fromDate = format.parse(fromDate).toCalendar()
                    basicDetails.toDate = format.parse(toDate).toCalendar()
                }
            }
        }
        processedBankStatementVO.statementStatus.statementParsedStatus = Enums.StatementParsedStatus.PARTIALLY_PARSED
        processedBankStatementVO.statementStatus.message = "Basic details extracted Successfully"
        reader.close()
    }

