//    ================================ Common date handling for statement tables ==================================

    public static String correctMonthName(String monthName) {
        if (!monthName) {
            return monthName
        }
        String month = monthName.trim().toUpperCase()
        Map<String, String> monthNameMap = monthNameCorrectionDictionary()
        monthNameMap.containsKey(month) ? monthNameMap.get(month) : month
    }

    /**
     * Normalizes a date extracted from a statement table so that a single {@link SimpleDateFormat} is able to parse
     * every flavour of month name based dates printed by the banks. Numeric dates are returned untouched.
     */
    public static String normalizeDateString(String dateString) {
        if (!dateString) {
            return dateString
        }
        String date = dateString.replaceAll(String.valueOf(160 as char), " ").trim()
        date = date.replaceAll("[\\s]+", " ")
        java.util.regex.Matcher dateMatcher = java.util.regex.Pattern.compile(MONTH_NAME_DATE_REGEX).matcher(date)
        if (dateMatcher.matches()) {
            String day = dateMatcher.group(1)
            day = day.length() == 1 ? "0" + day : day
            String month = correctMonthName(dateMatcher.group(2))
            String year = dateMatcher.group(3)
            date = "${day}-${month}-${year}"
        }
        date
    }

