    public static Boolean isTransactionHeaderRow(Elements rowElements, BankTransactionHeaderIndex headerIndex) {
        Map<String, String> headerMap = headerDictionary()
        String date = cellText(rowElements, headerIndex?.transactionDateIndex).trim()
        String description = cellText(rowElements, headerIndex?.descriptionIndex).trim()
        String balance = cellText(rowElements, headerIndex?.balanceAfterTransactionIndex).trim()
        if (date && (date.find(headerMap.transaction_header) || date.find("[A-z]{4,}"))) {
