    public static void assignAmountAndType(BankTransactionResponse bankTransactionResponse, Elements rowElements,
                                           BankTransactionHeaderIndex headerIndex) {
        String debit = cellText(rowElements, headerIndex.debitIndex)
        if (headerIndex.debitIndex != null && debit && !debit.find("^[\\s]*(-[\\s]*)?\$")) {
            bankTransactionResponse.amount = HelperMethod.getSanitizeDouble(debit)
            bankTransactionResponse.type = Enums.BankTransactionType.DEBIT
        }
        String credit = cellText(rowElements, headerIndex.creditIndex)
        if (headerIndex.creditIndex != null && credit && !credit.find("^[\\s]*(-[\\s]*)?\$") &&
                (!bankTransactionResponse.amount || bankTransactionResponse.amount == 0d)) {
            bankTransactionResponse.amount = HelperMethod.getSanitizeDouble(credit)
            bankTransactionResponse.type = Enums.BankTransactionType.CREDIT
        }
        String amount = cellText(rowElements, headerIndex.amountIndex)
        if (headerIndex.amountIndex != null && amount && (!bankTransactionResponse.amount || bankTransactionResponse.amount == 0d)) {
            bankTransactionResponse.amount = HelperMethod.getSanitizeDouble(amount)
        }
        String amountType = cellText(rowElements, headerIndex.amountTypeIndex)
