package sandbox

class Slog {
    void debug(Object o) {}
    void error(Object o) { println "ERROR: ${o}" }
    void error(Object o, Throwable t) { println "ERROR: ${o}"; t.printStackTrace() }
}

class Enums {
    static enum BankTransactionType { DEBIT, CREDIT }
    static enum StatementParsedStatus { INITIALISED, PARTIALLY_PARSED, TRANSACTION_PARTIALLY_PARSED, ERROR, UNSUPPORTED_FILE, CORRUPT_FILE, SCANNED_FILE }
    static enum Bank { ANDHRA_BANK, HSBC }
}

class AppConstant {
    static final String currencyRegex = "[\\s]*[+-]?(\\d{1,3},)*\\d+\\.\\d{1,2}"
    static final String dateRegex = "[0-3]?[0-9][-/][0-3]?[0-9][-/](?:[0-9]{2})?[0-9]{2}"
}

class AppUtil {
    static String getStackTraceAsString(Throwable t) { t.toString() }
}

class HelperMethod {
    static Double getSanitizeDouble(String value) {
        if (!value) return 0d
        String v = value.replaceAll("[^0-9.\\-]", "")
        if (!v || v == "-" || v == ".") return 0d
        try { return Double.parseDouble(v) } catch (Exception e) { return 0d }
    }

    static BigDecimal roundTo2Places(def value) {
        new BigDecimal(value as String).setScale(2, java.math.RoundingMode.HALF_UP)
    }
}

class BankTransactionResponse {
    Date transactionDate
    Date valueDate
    String description
    Enums.BankTransactionType type
    Double amount
    BigDecimal balanceAfterTransaction
    String remark

    void setBalanceAfterTransaction(def value) {
        this.balanceAfterTransaction = value == null ? null : new BigDecimal(value as String)
    }

    String toString() {
        "${transactionDate?.format('yyyy-MM-dd')} | '${description}' | ${type} | ${amount} | ${balanceAfterTransaction} | remark='${remark}'"
    }
}

