/**
 * Basic detail extraction for every HSBC current account layout. The account holder name is printed either on the
 * 'Statement Date' line or on the 'Acc name' line, the account number always uses the 999-999999-999 format.
 */
public
static void extractBasicInformationFromDownloadedCurrentAccount(ProcessedBankStatementVO processedBankStatementVO) {
    File textFile = processedBankStatementVO.processBankStatementCO.textFile
    if (!AppUtil.isValidStatementFile(textFile, ["Account[\\s]*Statement", "Statement[\\s]*Details"]) &&
            !AppUtil.isValidStatementFile(textFile, ["Account[\\s]*number", "Additional[\\s]*narrative"])) {
        return
    }
    BufferedReader reader = new BufferedReader(new InputStreamReader(new FileInputStream(textFile), "UTF-8"))
    BasicDetailsResponse basicDetailsResponse = processedBankStatementVO.basicDetails
    Boolean isAccountNameFound = Boolean.FALSE
    String line = ""
    while (line != null) {
        line = reader.readLine()
        if (StringUtils.isBlank(line)) {
            continue
        } else if (line?.find("Acc[\\s]*name")) {
            basicDetailsResponse.accountHolderName = line?.find("(?<=name\\s).*(?=\\sAccount)")?.trim()
            isAccountNameFound = Boolean.TRUE
        } else if (!isAccountNameFound && line?.find("Statement[\\s]*Date")) {
            basicDetailsResponse.accountHolderName = line?.split("Statement")[0]?.trim()
        } else if (line?.find("[0-9]{3}-[0-9]{6}-[0-9]{3}") && line.find("Account[\\s]*[Nn]umber")) {
            String accountNumber = line.find("[0-9]{3}-[0-9]{6}-[0-9]{3}")
            basicDetailsResponse.accountNumber = HelperMethod.getSanitizeAccountNumber(accountNumber)
            break
        }
    }
    processedBankStatementVO.statementStatus.statementParsedStatus = Enums.StatementParsedStatus.PARTIALLY_PARSED
    processedBankStatementVO.statementStatus.message = "Basic details extracted Successfully"
    reader.close()
}

public
static String extractAccountHolderName(List<String> header, ProcessedBankStatementVO processedBankStatementVO) {
    String accountHolder = ""
    for (int lineNumber = 0; (lineNumber < header.size() && !accountHolder); lineNumber++) {
        try {
            String line = header.get(lineNumber)
            if (StringUtils.isBlank(line)) {
                continue
            } else if (line.find("Acc[\\s]*name")) {
                accountHolder = line.find("(?<=name\\s).*(?=\\sAccount)")?.trim()
            } else if (line.find("Statement[\\s]*Date")) {
                accountHolder = line.split("Statement")[0]?.trim()
            }
        } catch (Exception e) {
            println("== ERROR : An exception occurred while extracting ACCOUNT_HOLDER_NAME for ${processedBankStatementVO.processBankStatementCO.bank} bank ==> " + e)
            e.printStackTrace()
        }
    }
    BankUtil.cleanAccountHolderName(accountHolder)?.trim()
}

