    /**
     * Handles table based statements in which the continuation lines of a transaction are printed above the row that
     * carries the running balance. The transaction date is either printed on the balance bearing row itself or on one
     * of the continuation rows above it, hence a balance bearing row without its own date inherits the date collected
     * from the rows above it and, as a last resort, the date of the preceding transaction.
     */
    public
    static void extractTransactionsFromHTMLHavingDescriptionAboveDate(ProcessedBankStatementVO processedBankStatementVO) {
        String result = PDF2Table.fetchTransactionHTML(processedBankStatementVO.processBankStatementCO.bankStatement, processedBankStatementVO.processBankStatementCO.password)
        JSONArray resultList = new JSONArray(result)
        for (int i = 0; i < resultList.length(); i++) {
            org.jsoup.nodes.Document jsoupDoc = Jsoup.parse(resultList.get(i).toString())
            Elements elements = jsoupDoc.select("tr")
            if (!elements || elements.isEmpty()) {
                continue
            }
            BankTransactionHeaderIndex bankTransactionHeaderIndex = headerIndex(elements.first())
            if (isTransactionHeaderRow(elements.first().select("td"), bankTransactionHeaderIndex)) {
                elements.remove(0)
            }
            Boolean hasBalanceColumn = bankTransactionHeaderIndex.balanceAfterTransactionIndex != null
            Integer elementCount = elements.size()
            Integer lineCount = 0
            String description = ""
            String pendingDate = ""
            while (lineCount < elementCount) {
                try {
                    Elements rowElements = elements.get(lineCount).select("td")
                    String date = cellText(rowElements, bankTransactionHeaderIndex.transactionDateIndex).trim()
                    String balance = cellText(rowElements, bankTransactionHeaderIndex.balanceAfterTransactionIndex).trim()
                    String rowDescription = cellText(rowElements, bankTransactionHeaderIndex.descriptionIndex)
//                    Repeated transaction table headers and the trailing total rows are not transactions.
                    if (isTransactionHeaderRow(rowElements, bankTransactionHeaderIndex) ||
                            isJunkTransactionRow(rowElements, bankTransactionHeaderIndex)) {
                        lineCount += 1
                        continue
                    }
                    Boolean isTransactionRow = hasBalanceColumn ? (balance ? Boolean.TRUE : Boolean.FALSE) :
                            (date ? Boolean.TRUE : Boolean.FALSE)
                    if (!isTransactionRow) {
                        if (!isOpeningBalanceRow(rowDescription)) {
                            description = description + " " + rowDescription
                        }
                        if (date && isDateString(date)) {
                            pendingDate = date
                        }
                        lineCount += 1
                        continue
                    }
                    String transactionDate = date ?: pendingDate
                    if (isOpeningBalanceRow(rowDescription) || isOpeningBalanceRow(description)) {
                        if (!processedBankStatementVO.bankTransactionList) {
                            BankTransactionResponse openingBalanceTransaction =
                                    BankUtil.createOpeningBalanceTransaction(BankUtil.processBalanceAmount(balance))
                            openingBalanceTransaction.transactionDate = fetchTransactionDate(transactionDate)
                            openingBalanceTransaction.valueDate = openingBalanceTransaction.transactionDate
                            processedBankStatementVO.bankTransactionList << openingBalanceTransaction
                        }
                        description = ""
                        pendingDate = ""
                        lineCount += 1
                        continue
                    }
                    BankTransactionResponse bankTransactionResponse = new BankTransactionResponse()
                    bankTransactionResponse.transactionDate = fetchTransactionDate(transactionDate)
                    if (!bankTransactionResponse.transactionDate && processedBankStatementVO.bankTransactionList) {
                        bankTransactionResponse.transactionDate = processedBankStatementVO.bankTransactionList.last().transactionDate
                    }
                    String valueDate = cellText(rowElements, bankTransactionHeaderIndex.valueDateIndex).trim()
                    bankTransactionResponse.valueDate = valueDate ? fetchTransactionDate(valueDate) : null
                    description = description + " " + rowDescription
                    bankTransactionResponse.description = description.trim()
                    bankTransactionResponse.remark = cellText(rowElements, bankTransactionHeaderIndex.chequeNoIndex)
                    bankTransactionResponse.balanceAfterTransaction = BankUtil.processBalanceAmount(balance)
                    assignAmountAndType(bankTransactionResponse, rowElements, bankTransactionHeaderIndex)
                    processedBankStatementVO.bankTransactionList << bankTransactionResponse
                    description = ""
                    pendingDate = ""
                } catch (Exception e) {
                    processedBankStatementVO.statementStatus.statementParsedStatus = Enums.StatementParsedStatus.TRANSACTION_PARTIALLY_PARSED
                    processedBankStatementVO.statementStatus.exceptionStackTrace = AppUtil.getStackTraceAsString(e)
                    processedBankStatementVO.statementStatus.message = "Exception occurred during parsing ${processedBankStatementVO.processBankStatementCO.bank} download statement 'HTMLHavingDescriptionAboveDate' ====>>>>>> ${e.message}"
                    log.error(processedBankStatementVO.statementStatus.message, e)
                }
                lineCount += 1
            }
        }
